require("Game.Views.ItemViews.VernierCommonItem")
ItemVernierCommon = class("ItemVernierCommon")

function ItemVernierCommon:ctor()
end

function ItemVernierCommon:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    self.usedItemList = {};
    self.recycledItemList = {};
    self.itemOnClick = nil;
end

function ItemVernierCommon:FindComponent(transform)
    local tTransform = transform;
    self.scrollView = Util.FindChildEx(tTransform,"ScrollView"):GetComponent("UIScrollView");
    self.grid = Util.FindChildEx(tTransform,"ScrollView/WrapContent"):GetComponent("UIWrapContent");
    self.recovery = Util.FindChildEx(tTransform,"ScrollView/recovery");
    self.obj_item = Util.FindChildEx(tTransform,"ScrollView/recovery/Hero");
end

function ItemVernierCommon:Init(data, itemOnClick)

end

function ItemVernierCommon:SetItemList(data)
    PrefabTool.AdjustPrefabItemCount(#data.itemList, self.recovery, self.grid.transform,
            self.usedItemList, self.recycledItemList, self.obj_item, VernierCommonItem);
    for i = 1, #self.usedItemList do
        --self.usedItemList[i]:Init(data.skills[i], data.heroID);
    end
    self.grid:Reposition();
    self.scrollView:ResetPosition();
end